import {stateAt,stateCases,polymerCounts,validRepeat} from './structure-models.js?v=20261023-physicscomplete01';
import {showPhase,showMolecular,showStructure,repeatSVG,networkSVG} from './structure-scenes.js?v=20261023-physicscomplete01';
import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s);
const btn=(id,s)=>`<button class="secondary" id="${id}">${s}</button>`;
const sel=(id,label,options,value='')=>`<label class="field-label" for="${id}">${label}</label><select id="${id}" class="lab-select">${options.map(([v,s])=>`<option value="${v}" ${v===value?'selected':''}>${s}</option>`).join('')}</select>`;
const input=(id,label,value='',max=100)=>`<label class="field-label" for="${id}">${label}</label><input id="${id}" class="lab-input" type="number" min="0" max="${max}" value="${value}">`;
export function mountStructureWidget(l,p,root,{save,done,feedback}){
 const w=p.widget;w.passed??=[];const pass=msg=>{p.widgetDone=true;save();done();feedback(msg);};const again=()=>{save();mountStructureWidget(l,p,root,{save,done,feedback});};
 if(l.widget==='states-lab'){
 w.case??=0;w.guesses??={};w.symbols??=['','','',''];const i=w.case,t=stateCases[i];
 root.innerHTML=`<p><b>${t.name}: melting ${t.mp} °C · boiling ${t.bp} °C</b></p><p>Predict the state at <strong>${t.t} °C</strong> at the same fixed pressure. The arrangement appears after your prediction.</p>`+sel('statePrediction','Your prediction',[['','Choose a state'],['solid','Solid'],['liquid','Liquid'],['gas','Gas'],['solid + liquid','Solid and liquid can coexist'],['liquid + gas','Liquid and gas can coexist']],w.guesses[i]||'')+btn('checkState','Check and reveal')+btn('nextState','Next sample →')+`<p id="stateProgress">${w.passed.filter(x=>typeof x==='number').length} / 4 predictions correct</p><p>Complete the symbols: HCl(__) + NaOH(__) → NaCl(__) + H₂O(__). The acid, alkali and salt are dissolved in water.</p><div class="diagram-inputs">`+['HCl','NaOH','NaCl','H₂O'].map((name,j)=>sel('symbol'+j,name,[['','Choose'],['s','(s)'],['l','(l)'],['g','(g)'],['aq','(aq)']],w.symbols[j])).join('')+'</div>'+btn('checkSymbols','Check the state symbols');
 const reveal=()=>{const s=stateAt(t.t,t.mp,t.bp);showPhase(s);};if(w.passed.includes(i))reveal();else renderDiagram('Predict before revealing',`${t.t} °C`,'<div class="diagram-card"><p>Melting point: '+t.mp+' °C</p><p>Boiling point: '+t.bp+' °C</p><p>Compare the temperature with both boundaries.</p></div>','DATA AT FIXED PRESSURE');
 const finish=()=>{if(w.passed.length===5)pass('All four state predictions and the aqueous/liquid equation are correct.');};$('#statePrediction').onchange=e=>{w.guesses[i]=e.target.value;save();};$('#checkState').onclick=()=>{const answer=stateAt(t.t,t.mp,t.bp);if(w.guesses[i]===answer){if(!w.passed.includes(i))w.passed.push(i);save();$('#stateProgress').textContent=w.passed.filter(x=>typeof x==='number').length+' / 4 predictions correct';reveal();feedback('Correct: '+answer+'. '+(t.t===t.mp?'At melting, solid and liquid can coexist.':'Compare the temperature with the melting and boiling points.'));finish();}else feedback('Check both boundaries. At a transition temperature, two states may coexist. Try again before revealing the arrangement.',true);};$('#nextState').onclick=()=>{w.case=(i+1)%4;again();};[0,1,2,3].forEach(j=>$('#symbol'+j).onchange=e=>{w.symbols[j]=e.target.value;save();});$('#checkSymbols').onclick=()=>{if(w.symbols.join(',')==='aq,aq,aq,l'){if(!w.passed.includes('symbols'))w.passed.push('symbols');save();feedback('Correct: HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l).');finish();}else feedback('The three solutes are aqueous. The water is liquid, not a dissolved solute.',true);};return;
 }
 if(l.widget==='molecular-lab'){
 w.apart??=false;w.answers??={};root.innerHTML='<p>Predict what is overcome when water boils, then separate the molecules. Their covalent O–H bonds should remain intact.</p><div class="choices"><button class="choice" data-force="between">Forces between molecules</button><button class="choice" data-force="within">O–H covalent bonds inside molecules</button></div>'+btn('bringTogether','Bring molecules together')+btn('separateMolecules','Separate the molecules')+'<p class="micro-note">3D shows covalent bonds only. Switch to 2D for dashed intermolecular-force guides. Distances are exaggerated.</p><table class="science-data"><caption>Related hydrocarbons · boiling data at the same pressure</caption><thead><tr><th>Formula</th><th>Carbon atoms</th><th>Boiling / °C</th></tr></thead><tbody><tr><td>CH₄</td><td>1</td><td>−162</td></tr><tr><td>C₂H₆</td><td>2</td><td>−89</td></tr><tr><td>C₃H₈</td><td>3</td><td>−42</td></tr></tbody></table>'+sel('trendPrediction','For the next member, predict the boiling-point trend',[['','Choose'],['higher','Higher'],['lower','Lower']],w.answers.trend||'')+sel('currentPrediction','What carries current in a pure molecular substance with no ions or delocalised electrons?',[['','Choose'],['none','No mobile charge carrier is available'],['molecules','The neutral molecules carry charge']],w.answers.current||'')+btn('checkMolecular','Check the explanations');
 const draw=()=>showMolecular(w.apart);draw();root.querySelectorAll('[data-force]').forEach(b=>b.onclick=()=>{if(b.dataset.force==='between'){if(!w.passed.includes('force'))w.passed.push('force');save();feedback('Correct. Now separate intact molecules; boiling does not break their O–H bonds.');}else feedback('Breaking O–H bonds is chemical change. Boiling overcomes attractions between intact molecules.',true);});$('#separateMolecules').onclick=()=>{if(!w.passed.includes('force')){feedback('Make the correct prediction about the forces first.',true);return;}w.apart=true;if(!w.passed.includes('separated'))w.passed.push('separated');save();draw();};$('#bringTogether').onclick=()=>{w.apart=false;save();draw();};$('#trendPrediction').onchange=e=>{w.answers.trend=e.target.value;save();};$('#currentPrediction').onchange=e=>{w.answers.current=e.target.value;save();};$('#checkMolecular').onclick=()=>{if(!w.passed.includes('separated'))feedback('First predict and separate the intact molecules.',true);else if(w.answers.trend==='higher'&&w.answers.current==='none')pass('Correct. Larger related molecules have stronger intermolecular forces; neutral molecules alone do not provide mobile charge.');else feedback('Read the boiling-point trend: less negative is higher. Conduction needs a mobile charged particle, not just moving neutral molecules.',true);};return;
 }
 if(l.widget==='polymer-lab'){
 w.repeat??={cc:0,ch:0,left:0,right:0};w.n??=3;w.h??='';const v=w.repeat;
 root.innerHTML='<p>Construct the displayed repeating unit of poly(ethene). All atoms are supplied. Add single bonds, including continuation bonds through both brackets.</p><div class="diagram-inputs">'+[['cc','C–C bonds inside brackets',1],['ch','C–H bonds inside brackets',4],['left','Bonds continuing left',1],['right','Bonds continuing right',1]].map(([k,t,max])=>input('repeat'+k,t,v[k],max)).join('')+'</div>'+btn('checkRepeat','Check my repeating unit')+`<label class="field-label" for="repeatN">Repeat count n: <span id="repeatValue">${w.n}</span></label><input id="repeatN" type="range" min="2" max="8" value="${w.n}">`+input('polymerH','How many H atoms for this n? Ignore end groups.',w.h)+btn('checkPolymerCount','Check the atom count')+sel('polymerReason','Why are many polymers solids at room temperature?',[['','Choose'],['forces','Relatively strong attractions between long chains'],['none','There are no forces between chains']],w.reason||'')+btn('checkPolymerReason','Check the explanation')+btn('polymer3D','Explore separate chain fragments in 3D')+'<p class="micro-note">This repeat-count calculation ignores end groups. The 3D carbon skeleton omits hydrogen atoms; it is a fragment, not a whole molecule.</p>';
 const draw=()=>{renderDiagram('Build the repeating unit',`–[CH₂–CH₂]– · n = ${w.n}`,repeatSVG(v),'SINGLE BONDS · BRACKETS · CONTINUATION');save();};const finish=()=>{if(['repeat','count','reason'].every(x=>w.passed.includes(x)))pass('Repeating unit, atom count and chain-property explanation complete.');};
 Object.keys(v).forEach(k=>$('#repeat'+k).oninput=e=>{v[k]=Math.max(0,Math.min(k==='ch'?4:1,Math.floor(Number(e.target.value)||0)));draw();});$('#checkRepeat').onclick=()=>{if(validRepeat(v)){if(!w.passed.includes('repeat'))w.passed.push('repeat');save();feedback('Correct: each C has four single bonds, including continuation at the chain edges.');finish();}else feedback('Each carbon needs four bonds: one to the other carbon, two to H, and one continuing beyond the bracket. All are single bonds.',true);};$('#repeatN').oninput=e=>{w.n=Number(e.target.value);w.h='';$('#polymerH').value='';$('#repeatValue').textContent=w.n;w.passed=w.passed.filter(x=>x!=='count');p.widgetDone=false;draw();};$('#polymerH').oninput=e=>{w.h=e.target.value;save();};$('#checkPolymerCount').onclick=()=>{if(w.h!==''&&Number(w.h)===polymerCounts(w.n).H){if(!w.passed.includes('count'))w.passed.push('count');save();feedback(`Correct: four H per unit × ${w.n} units = ${4*w.n}.`);finish();}else feedback('Count four hydrogen atoms per whole repeating unit, then multiply by n.',true);};$('#polymerReason').onchange=e=>{w.reason=e.target.value;save();};$('#checkPolymerReason').onclick=()=>{if(w.reason==='forces'){if(!w.passed.includes('reason'))w.passed.push('reason');save();feedback('Correct: large chains have relatively strong intermolecular attractions.');finish();}else feedback('Distinguish the covalent bonds along a chain from attractions between separate chains.',true);};$('#polymer3D').onclick=()=>showStructure('polymer');draw();return;
 }
 if(l.widget==='network-lab'){
 w.case??=0;const i=w.case;const cases=[['small','Separate small molecules','<div class="diagram-card"><p>H—Cl &nbsp;&nbsp; H—Cl &nbsp;&nbsp; H—Cl</p><p>Three separate bonded groups.</p></div>'],['polymer','Separate long molecules',repeatSVG()],['giant','Continuous covalent network',networkSVG()]];const t=cases[i];root.innerHTML=`<p><b>Diagram ${i+1} / 3</b></p><p>Classify the covalently bonded structure using the connections. Then explain its energy requirement.</p>`+sel('structureChoice','Structure type',[['','Choose'],['small','Small molecules'],['polymer','Polymer molecules'],['giant','Giant covalent network']],w['guess'+i]||'')+btn('checkStructure','Check the classification')+btn('nextStructure','Next diagram →')+`<p id="networkProgress">${w.passed.filter(x=>typeof x==='number').length} / 3 classified</p>`+sel('networkEnergy','Why does silica have a very high melting point?',[['','Choose'],['bonds','Many strong covalent bonds need energy to overcome'],['weak','Only weak forces between small SiO₂ molecules are overcome']],w.energy||'')+btn('checkNetworkEnergy','Check the energy explanation');renderDiagram('Read the connections','Diagram '+(i+1),t[2],'SCHEMATIC · FRAGMENT / SAMPLE ONLY');
 const finish=()=>{if(w.passed.length===4)pass('All three structures classified and the giant-network explanation correct.');};$('#structureChoice').onchange=e=>{w['guess'+i]=e.target.value;save();};$('#checkStructure').onclick=()=>{if(w['guess'+i]===t[0]){if(!w.passed.includes(i))w.passed.push(i);save();$('#networkProgress').textContent=w.passed.filter(x=>typeof x==='number').length+' / 3 classified';feedback('Correct: '+t[1]+'.');finish();}else feedback('Look for small separate groups, a long repeating chain, or a network continuing in several directions.',true);};$('#nextStructure').onclick=()=>{w.case=(i+1)%3;again();};$('#networkEnergy').onchange=e=>{w.energy=e.target.value;save();};$('#checkNetworkEnergy').onclick=()=>{if(w.energy==='bonds'){if(!w.passed.includes('energy'))w.passed.push('energy');save();feedback('Correct: silica is a network of strong covalent bonds, not separate SiO₂ molecules.');finish();}else feedback('Use the continuous network: many strong covalent bonds must be overcome.',true);};
 }
}
